"use client";

import { useState, useRef } from "react";
import { Upload, X, FileCheck, Shield, Lock } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

interface FileUploadProps {
    onFileSelect: (file: File | null) => void;
}

export default function FileUpload({ onFileSelect }: FileUploadProps) {
    const [file, setFile] = useState<File | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(true);
    };

    const handleDragLeave = () => {
        setIsDragging(false);
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
        const droppedFile = e.dataTransfer.files[0];
        if (droppedFile && droppedFile.type === "application/pdf") {
            setFile(droppedFile);
            onFileSelect(droppedFile);
        }
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const selectedFile = e.target.files?.[0];
        if (selectedFile) {
            setFile(selectedFile);
            onFileSelect(selectedFile);
        }
    };

    const clearFile = (e: React.MouseEvent) => {
        e.stopPropagation();
        setFile(null);
        onFileSelect(null);
        if (fileInputRef.current) fileInputRef.current.value = "";
    };

    return (
        <div
            onClick={() => fileInputRef.current?.click()}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
            className={`
                relative group cursor-pointer overflow-hidden p-10 transition-all duration-100 brutalist-card !bg-black text-white
                ${isDragging ? "!bg-primary !text-black -translate-x-1 -translate-y-1" : "hover:border-primary/40"}
            `}
        >
            <input
                type="file"
                ref={fileInputRef}
                onChange={handleChange}
                className="hidden"
                accept="application/pdf"
            />

            <div className="relative z-10 flex flex-col items-center text-center gap-6">
                <div className={`w-16 h-16 border-[3px] border-black shadow-brutalist-sm flex items-center justify-center transition-colors duration-100 ${isDragging || file ? 'bg-white text-black' : 'bg-primary text-black'}`}>
                    {isDragging ? (
                        <Shield className="w-8 h-8 animate-bounce" />
                    ) : file ? (
                        <FileCheck className="w-8 h-8" />
                    ) : (
                        <Upload className="w-8 h-8" />
                    )}
                </div>

                <AnimatePresence mode="wait">
                    {!file ? (
                        <motion.div
                            key="empty"
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            className="space-y-3"
                        >
                            <h3 className="font-arcade text-xs">
                                {isDragging ? "RELEASE TO INGEST" : "INSERT STATEMENT"}
                            </h3>
                            <p className="font-mono text-[9px] font-bold text-white/40 uppercase tracking-widest">
                                1P START - PDF ONLY
                            </p>
                            <div className="pt-4 flex items-center justify-center gap-4">
                                <div className="w-6 h-[2px] bg-white/10" />
                                <Lock className="w-3 h-3 text-secondary" />
                                <div className="w-6 h-[2px] bg-white/10" />
                            </div>
                        </motion.div>
                    ) : (
                        <motion.div
                            key="file"
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            className="space-y-4"
                        >
                            <div className="px-4 py-1 bg-primary text-black font-arcade text-[6px] shadow-brutalist-sm inline-block">
                                DATA_SECURED_V1
                            </div>
                            <h3 className="font-mono font-bold text-md tracking-tight truncate max-w-[200px] mx-auto">
                                {file.name.toUpperCase()}
                            </h3>
                            <button
                                onClick={clearFile}
                                className="font-arcade text-[7px] text-secondary hover:underline"
                            >
                                [ EJECT_MODULE ]
                            </button>
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>
        </div>
    );
}

"use client";

import { motion } from "framer-motion";
import ReactMarkdown from "react-markdown";
import { ShieldAlert, Activity, Fingerprint } from "lucide-react";
import Image from "next/image";

interface RoastCardProps {
    roast: string;
}

export default function RoastCard({ roast }: RoastCardProps) {
    return (
        <motion.div
            initial={{ opacity: 0, scale: 0.98 }}
            animate={{ opacity: 1, scale: 1 }}
            className="brutalist-card !bg-white p-12 md:p-16 relative group overflow-hidden border-[4px] shadow-brutalist-lg"
        >
            {/* Tactical Decal */}
            <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
                <Fingerprint className="w-64 h-64 text-black" />
            </div>

            <div className="relative z-10 flex flex-col md:flex-row gap-12 items-start">
                <div className="shrink-0 flex flex-col items-center">
                    <div className="w-24 h-24 bg-secondary rounded-none border-[4px] border-black flex items-center justify-center shadow-brutalist relative">
                        <ShieldAlert className="w-12 h-12 text-white" />
                    </div>
                    <div className="mt-10 text-center space-y-6">
                        <span className="block font-arcade text-[10px] text-black/40 uppercase tracking-widest">Audit Log</span>
                        <div className="px-6 py-3 bg-black border-[3px] border-black flex items-center gap-4">
                            <div className="w-3 h-3 bg-primary animate-pulse" />
                            <span className="font-arcade text-[9px] text-primary uppercase tracking-widest">Active</span>
                        </div>
                    </div>
                </div>

                <div className="flex-1 max-w-none text-black overflow-hidden font-mono">
                    <ReactMarkdown
                        components={{
                            p: ({ children }) => <p className="text-2xl font-black leading-relaxed text-black mb-10 tracking-tight">{children}</p>,
                            strong: ({ children }) => <strong className="text-secondary font-black underline decoration-4 underline-offset-8">{children}</strong>,
                            li: ({ children }) => (
                                <motion.li
                                    initial={{ opacity: 0, x: -10 }}
                                    whileInView={{ opacity: 1, x: 0 }}
                                    className="text-xl text-black/80 font-bold mb-6 flex gap-6 items-start before:content-['>>'] before:text-primary before:font-black"
                                >
                                    {children}
                                </motion.li>
                            ),
                            ul: ({ children }) => <ul className="list-none p-0 my-10 space-y-4">{children}</ul>,
                            h2: ({ children }) => <h2 className="font-arcade text-lg text-secondary mt-16 mb-8 border-b-[4px] border-secondary/10 pb-4 tracking-tighter">{children}</h2>
                        }}
                    >
                        {roast}
                    </ReactMarkdown>
                </div>
            </div>

            <div className="mt-12 pt-8 border-t-[2px] border-white/10 flex justify-between items-center relative z-10">
                <div className="flex items-center gap-4">
                    <span className="font-arcade text-[8px] text-muted-foreground">ID: RUPEE_ROAST_S3</span>
                </div>
                <div className="flex gap-2">
                    <div className="w-8 h-2 bg-primary/20" />
                    <div className="w-4 h-2 bg-primary/40" />
                    <div className="w-2 h-2 bg-primary" />
                </div>
            </div>

            {/* Visual Asset Integration */}
            <div className="absolute -bottom-6 -right-6 scale-75 md:scale-100">
                <Image
                    src="/assets/rupee-roast/sticker_crying_wallet.png"
                    alt="Regret"
                    width={128}
                    height={128}
                    className="w-32 h-32 -rotate-12"
                />
            </div>
        </motion.div>
    );
}

"use client";

import { AnalysisResult, Transaction } from "../types";
import {
    MoreHorizontal, ListFilter,
    ChevronDown, ArrowDownLeft, Trash2, Rocket
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { useState } from "react";
import Image from "next/image";

interface SpendingBreakdownProps {
    analysis: AnalysisResult;
}

const CATEGORY_ASSETS: Record<string, string> = {
    Food: "/assets/rupee-roast/icon_burger.png",
    Travel: "/assets/rupee-roast/icon_taxi.png",
    Shopping: "/assets/rupee-roast/icon_bag.png",
    Other: "/assets/rupee-roast/icon_burger.png", // Fallback
};

export default function SpendingBreakdown({ analysis }: SpendingBreakdownProps) {
    const [showAllTransactions, setShowAllTransactions] = useState(false);

    const debits = analysis.transactions.filter(t => t.transaction_type === "DEBIT");
    const credits = analysis.transactions.filter(t => t.transaction_type === "CREDIT");

    const totalSpent = debits.reduce((sum, t) => sum + (t.amount || 0), 0);
    const totalReceived = credits.reduce((sum, t) => sum + (t.amount || 0), 0);

    const grouped = debits.reduce((acc, t) => {
        const cat = t.category;
        if (!acc[cat]) acc[cat] = { transactions: [], total: 0 };
        acc[cat].transactions.push(t);
        acc[cat].total += (t.amount || 0);
        return acc;
    }, {} as Record<string, { transactions: Transaction[]; total: number }>);

    const sortedCategories = Object.entries(grouped).sort((a, b) => b[1].total - a[1].total);

    return (
        <div className="space-y-16">
            {/* Summary Grid */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                <div className="md:col-span-2 brutalist-card p-12 flex flex-col justify-between border-[4px] shadow-brutalist-lg bg-white">
                    <div>
                        <span className="font-arcade text-[12px] block mb-6 text-black/60 tracking-widest">TOTAL DAMAGE</span>
                        <div className="flex items-baseline gap-4 tabular font-black text-7xl text-black">
                            <span>₹{totalSpent.toLocaleString()}</span>
                        </div>
                    </div>
                    <div className="mt-12">
                        <p className="font-arcade text-[10px] text-black/40 mb-3 tracking-widest">CHAOS LEVEL</p>
                        <div className="h-10 w-full bg-black/5 border-[4px] border-black rounded-none overflow-hidden p-1">
                            <motion.div
                                initial={{ width: 0 }}
                                animate={{ width: "92%" }}
                                className="h-full bg-black shadow-[0_0_20px_rgba(0,0,0,0.5)] flex items-center justify-end px-4"
                            >
                                <span className="text-white text-[10px] font-arcade animate-pulse">CRITICAL</span>
                            </motion.div>
                        </div>
                    </div>
                </div>

                <div className="pink-card p-10 flex flex-col justify-between border-[4px] shadow-brutalist-lg">
                    <span className="font-arcade text-[10px] block mb-6 tracking-widest">INFLOW (LUCKY)</span>
                    <p className="text-4xl font-black tabular drop-shadow-lg">₹{totalReceived.toLocaleString()}</p>
                    <div className="mt-6 flex items-center gap-3">
                        <ArrowDownLeft className="w-6 h-6" />
                        <span className="font-arcade text-[10px]">BAILOUT</span>
                    </div>
                </div>

                <div className="indigo-card !bg-black p-10 flex flex-col justify-between border-[4px] border-primary shadow-neon-lime">
                    <span className="font-arcade text-[10px] block mb-6 text-primary tracking-widest">SESSION LOGS</span>
                    <p className="text-5xl font-black tabular text-primary">{analysis.transactions.length}</p>
                    <p className="font-arcade text-[10px] text-primary/40 uppercase mt-4">ENTRIES_AUDITED</p>
                </div>
            </div>

            {/* Category HUD */}
            {sortedCategories.length > 0 && (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                    {sortedCategories.slice(0, 3).map(([name, group], idx) => {
                        const iconPath = CATEGORY_ASSETS[name] || CATEGORY_ASSETS.Other;
                        return (
                            <motion.div
                                key={name}
                                whileHover={{ y: -10, scale: 1.02 }}
                                className="brutalist-card bg-white p-10 flex border-[4px] shadow-brutalist-lg"
                            >
                                <div className="flex-1">
                                    <Image
                                        src={iconPath}
                                        alt={name}
                                        width={64}
                                        height={64}
                                        className="w-16 h-16 mb-8 pixel-antialiased drop-shadow-md"
                                    />
                                    <h4 className="font-arcade text-[10px] text-black/50 mb-3 uppercase tracking-widest">{name}</h4>
                                    <p className="text-4xl font-black tabular">₹{group.total.toLocaleString()}</p>
                                </div>
                                <div className="font-arcade text-[10px] pt-4 text-primary drop-shadow-[1px_1px_0px_#000]">
                                    TOP L
                                </div>
                            </motion.div>
                        );
                    })}
                </div>
            )}

            {/* Receipt of Shame */}
            <div className="bg-white brutalist-card !p-0 overflow-hidden border-[4px] shadow-brutalist-lg">
                <div className="p-12 border-b-[4px] border-black bg-slate-50 flex items-center justify-between">
                    <div className="flex items-center gap-8">
                        <div className="w-16 h-16 bg-black text-white flex items-center justify-center border-[4px] border-black shadow-brutalist-sm">
                            <ListFilter className="w-8 h-8 text-primary" />
                        </div>
                        <div>
                            <h3 className="font-arcade text-lg tracking-tighter">RECEIPT OF SHAME</h3>
                            <span className="font-mono font-black text-[11px] text-black/40 uppercase tracking-[0.3em]">Date: {new Date().toLocaleDateString()} // P-885 // AUDIT_SIG: ALPHA</span>
                        </div>
                    </div>
                </div>

                <div className="receipt-edge h-6 w-full opacity-20" />

                <div className="p-6 space-y-2 relative">
                    <div className="absolute inset-0 pointer-events-none opacity-5 bg-[url('https://www.transparenttextures.com/patterns/paper.png')]" />

                    {analysis.transactions.map((t, i) => {
                        const iconPath = CATEGORY_ASSETS[t.category] || CATEGORY_ASSETS.Other;
                        const isCredit = t.transaction_type === "CREDIT";

                        return (
                            <div key={i} className="group/row relative">
                                <motion.div
                                    initial={{ opacity: 0, x: -10 }}
                                    animate={{ opacity: 1, x: 0 }}
                                    transition={{ delay: i * 0.02 }}
                                    className="flex items-center justify-between p-8 border-b-2 border-dashed border-black/10 hover:bg-primary/5 transition-all cursor-help"
                                >
                                    <div className="flex items-center gap-8">
                                        <div className={`w-14 h-14 border-[3px] border-black shadow-brutalist-sm flex items-center justify-center transition-colors ${isCredit ? 'bg-primary' : 'bg-white group-hover/row:bg-primary'}`}>
                                            <Image
                                                src={iconPath}
                                                alt={t.category}
                                                width={40}
                                                height={40}
                                                className="w-10 h-10 pixel-antialiased"
                                            />
                                        </div>
                                        <div>
                                            <p className="font-mono font-black text-lg tracking-tight text-black">{t.merchant.toUpperCase()}</p>
                                            <div className="flex items-center gap-4 mt-2">
                                                <span className="font-arcade text-[8px] text-black/40 tracking-widest">{t.category}</span>
                                                <span className={`font-arcade text-[8px] ${isCredit ? 'text-green-600' : 'text-secondary'}`}>[{t.transaction_type}]</span>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <p className={`text-2xl font-black tabular ${isCredit ? 'text-green-600' : 'text-black'}`}>
                                            {isCredit ? '+' : '-'}₹{t.amount?.toLocaleString()}
                                        </p>
                                        {t.is_impulsive && (
                                            <span className="font-arcade text-[7px] bg-secondary text-white px-3 py-1 mt-2 inline-block shadow-brutalist-sm">BURNING CAPITAL</span>
                                        )}
                                    </div>
                                </motion.div>

                                {/* Regret Tooltip */}
                                <div className="absolute top-0 right-full mr-8 z-[100] scale-0 group-hover/row:scale-110 transition-transform origin-right pointer-events-none">
                                    <div className="yellow-card w-56 p-6 rotate-[-2deg] border-[3px] shadow-brutalist bg-white text-black">
                                        <div className="flex items-center gap-3 mb-3">
                                            <Rocket className="w-4 h-4 text-primary" />
                                            <span className="font-arcade text-[8px] tracking-widest">REGRET_CALC</span>
                                        </div>
                                        <p className="font-mono text-[11px] font-black leading-tight uppercase">
                                            COULD HAVE BEEN <span className="text-green-600">₹{Math.round((t.amount || 0) * 1.3).toLocaleString()}</span> IF INVESTED IN NIFTY BEES.
                                        </p>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>

                <div className="receipt-edge h-6 w-full opacity-20 rotate-180" />

                <div className="p-12 bg-slate-50 border-t-[4px] border-black text-center">
                    <p className="font-arcade text-[10px] mb-6 text-black/40 tracking-[0.5em]">THANK YOU FOR YOUR POOR DECISIONS</p>
                    <div className="h-14 bg-black flex items-center justify-center border-[3px] shadow-brutalist">
                        <p className="font-arcade text-white text-[12px] tracking-[0.5em]">TOTAL REGRET: ₹{Math.round(totalSpent * 0.3).toLocaleString()}</p>
                    </div>
                </div>
            </div>
        </div>
    );
}
